{"witnessCode": "import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl stripWWW with 63-character TLD', () => {
  it('should strip www for 63-character TLD', () => {
    const tld = 'a'.repeat(63);
    const url = `http://www.a.${tld}/path`;
    const options = { stripWWW: true };

    const result = normalizeUrl(url, options);
    assert.strictEqual(result, `http://a.${tld}/path`);
  });
});"}
